/**
 * Every sound effect the client plays, combat (#104) and objectives (#1387).
 * This is the single list: each id has exactly one file at
 * `public/sfx/<id>.mp3`, generated by `scripts/assets/sfx.sh`, and `sfx-files.test.ts` holds the two together.
 */
export const SOUND_IDS = [
  "cast-self",
  "cast-target",
  "hit-dealt",
  "hit-taken",
  "heal",
  "interrupt",
  "interrupt-missed",
  "death",
  "refused",
  "weapon-swing",
  "bow-release",
  "objective-ours",
  "objective-theirs",
] as const;

export type SoundId = (typeof SOUND_IDS)[number];
